package no.slomic.smarthytte.reservations

import io.ktor.openapi.JsonSchema
import kotlinx.serialization.Serializable
import kotlin.time.Instant

/** A guest of a reservation in a request. Names and avatar are read-only and come from the guest. */
@Serializable
data class ReservationGuestRef(
    @JsonSchema.Description("Internal unique identifier of an existing guest, from GET /api/guests.")
    @JsonSchema.Example("\"ola.nordmann\"")
    val guestId: String,
)

/**
 * The request body of `POST /api/reservations`. The id is generated by the server. The UTC date of [startTime] and
 * [endTime] is the first and last day of the stay.
 */
@Serializable
data class ReservationCreate(
    @JsonSchema.Description(
        "When the stay starts (UTC instant). Its UTC date is the first day of the stay: an Oslo time between 00:00 " +
            "and 02:00 belongs to the previous UTC day. At most 2 years ahead, in the past is allowed.",
    )
    @JsonSchema.Example("\"2026-07-10T16:00:00Z\"")
    val startTime: Instant,
    @JsonSchema.Description(
        "When the stay ends (UTC instant), after startTime. Its UTC date is the last day of the stay, and at most " +
            "60 nights after the first day. It must not overlap another reservation: a handover where one " +
            "reservation ends at or before the time the next starts is allowed.",
    )
    @JsonSchema.Example("\"2026-07-12T13:00:00Z\"")
    val endTime: Instant,
    @JsonSchema.Description("The guests of the reservation: 1-50, each guest at most once, all existing.")
    val guests: List<ReservationGuestRef>,
)

/**
 * The request body of `PUT /api/reservations/{id}`: a full replace. The [version] the client read and every writable
 * property are required. Properties of the reservation that are not writable, such as `id`, `status`, check-in/out
 * and the audit fields, are ignored.
 */
@Serializable
data class ReservationUpdate(
    @JsonSchema.Description(
        "The version of the reservation that the client read, from GET /api/reservations. An outdated version " +
            "gives 412.",
    )
    @JsonSchema.Example("3")
    val version: Short,
    @JsonSchema.Description(
        "When the stay starts (UTC instant). Its UTC date is the first day of the stay: an Oslo time between 00:00 " +
            "and 02:00 belongs to the previous UTC day. At most 2 years ahead when the times change, in the past is " +
            "allowed.",
    )
    @JsonSchema.Example("\"2026-07-10T16:00:00Z\"")
    val startTime: Instant,
    @JsonSchema.Description(
        "When the stay ends (UTC instant), after startTime. Its UTC date is the last day of the stay, and at most " +
            "60 nights after the first day. It must not overlap another reservation. Changing the times clears the " +
            "check-in, the check-out and the linked trips of the reservation, which are derived again right " +
            "after the commit.",
    )
    @JsonSchema.Example("\"2026-07-12T13:00:00Z\"")
    val endTime: Instant,
    @JsonSchema.Description("The guests of the reservation: 1-50, each guest at most once, all existing.")
    val guests: List<ReservationGuestRef>,
)
